export enum DeliverabilityBand {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

export class EmailAccountEntity {
  smartleadInboxId: string;
  smartleadClientId: string;
  email: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  warmupReputation: number | null;
  deliverabilityScore: number | null;
  deliverabilityBand: DeliverabilityBand;
  numberOfCampaignAssociated: number;
  createdAt: string;
  updatedAt: string;

  constructor(partial: Partial<EmailAccountEntity> = {}) {
    Object.assign(this, partial);
    this.tags = this.tags || [];
    this.campaignIds = this.campaignIds || [];
    this.numberOfCampaignAssociated = this.campaignIds?.length || 0;
    this.updatedAt = new Date().toISOString();
    if (!this.createdAt) {
      this.createdAt = this.updatedAt;
    }
    this.domain = this.domain || this.extractDomain(this.email);
    this.deliverabilityScore = this.warmupReputation ?? null;
    this.deliverabilityBand = this.calculateDeliverabilityBand(
      this.deliverabilityScore,
    );
  }

  private extractDomain(email: string): string {
    const parts = email.split('@');
    return parts.length === 2 ? parts[1] : '';
  }

  private calculateDeliverabilityBand(
    score: number | null,
  ): DeliverabilityBand {
    if (score === null || score === undefined) {
      return DeliverabilityBand.Unknown;
    }
    if (score === 100) {
      return DeliverabilityBand.High;
    }
    if (score >= 98) {
      return DeliverabilityBand.Medium;
    }
    if (score >= 95) {
      return DeliverabilityBand.Low;
    }
    return DeliverabilityBand.Burned;
  }

  addCampaignId(campaignId: string): void {
    if (!this.campaignIds.includes(campaignId)) {
      this.campaignIds.push(campaignId);
      this.numberOfCampaignAssociated = this.campaignIds.length;
      this.updatedAt = new Date().toISOString();
    }
  }

  removeCampaignId(campaignId: string): void {
    const index = this.campaignIds.indexOf(campaignId);
    if (index !== -1) {
      this.campaignIds.splice(index, 1);
      this.numberOfCampaignAssociated = this.campaignIds.length;
      this.updatedAt = new Date().toISOString();
    }
  }

  hasCampaign(campaignId: string): boolean {
    return this.campaignIds.includes(campaignId);
  }

  updateReputation(score: number | null): void {
    this.warmupReputation = score;
    this.deliverabilityScore = score;
    this.deliverabilityBand = this.calculateDeliverabilityBand(score);
    this.updatedAt = new Date().toISOString();
  }

  addTag(tag: string): void {
    if (!this.tags.includes(tag)) {
      this.tags.push(tag);
      this.updatedAt = new Date().toISOString();
    }
  }

  removeTag(tag: string): void {
    const index = this.tags.indexOf(tag);
    if (index !== -1) {
      this.tags.splice(index, 1);
      this.updatedAt = new Date().toISOString();
    }
  }
}

