import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { DatastoreService } from '../datastore/datastore.service';
import { StoreDataDto } from '../datastore/dto/store.dto';
import { FindDataDto } from '../datastore/dto/find.dto';
import { documentType } from '../datastore/entites/documentType';
import {
  EmailAccountEntity,
  DeliverabilityBand,
} from './entities/email-account.entity';
import {
  EmailAccountDto,
  EmailAccountListDto,
  AssociateCampaignDto,
  EmailAccountFilterDto,
  SmartleadInboxResponseDto,
} from './dto/email-account.dto';

const EMAILS_PER_INBOX_PER_DAY = 20;

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  private readonly smartleadApiKey = process.env.SMARTLEAD_REPORT_API_KEY;
  private readonly smartleadBaseUrl = 'https://server.smartlead.ai/api/v1';

  constructor(private readonly datastoreService: DatastoreService) {}

  async saveEmailAccount(
    emailAccountDto: EmailAccountDto,
  ): Promise<EmailAccountEntity> {
    this.logger.log(
      `Saving email account: ${emailAccountDto.smartleadInboxId}`,
    );

    const existing = await this.getEmailAccountByInboxId(
      emailAccountDto.smartleadInboxId,
    );
    if (existing) {
      const updated = new EmailAccountEntity({
        ...existing,
        ...emailAccountDto,
        smartleadInboxId: existing.smartleadInboxId,
        createdAt: existing.createdAt,
      });
      await this.persistEmailAccount(updated);
      return updated;
    }

    const hydrated = await this.hydrateFromSmartlead(emailAccountDto);
    const entity = new EmailAccountEntity(hydrated);
    await this.persistEmailAccount(entity);
    return entity;
  }

  private async hydrateFromSmartlead(
    dto: EmailAccountDto,
  ): Promise<Partial<EmailAccountEntity>> {
    const inbox = await this.fetchSmartleadInbox(
      dto.smartleadInboxId,
      dto.smartleadClientId,
    );
    if (!inbox) {
      throw new NotFoundException(
        `Smartlead inbox not found: ${dto.smartleadInboxId}`,
      );
    }

    return {
      smartleadInboxId: inbox.id,
      smartleadClientId: dto.smartleadClientId,
      email: inbox.email,
      tags: inbox.tags || [],
      campaignIds: [],
      warmupReputation: inbox.warmup_reputation ?? null,
      createdAt: inbox.created_at || new Date().toISOString(),
    };
  }

  private async fetchSmartleadInbox(
    inboxId: string,
    clientId: string,
  ): Promise<SmartleadInboxResponseDto | null> {
    try {
      const url = `${this.smartleadBaseUrl}/email-accounts/${inboxId}?api_key=${this.smartleadApiKey}&client_id=${clientId}`;
      const res = await fetch(url);
      if (res.status === 404) {
        return null;
      }
      if (!res.ok) {
        throw new Error(`Smartlead API error: ${res.status}`);
      }
      return await res.json();
    } catch (error) {
      this.logger.error(
        `Failed to fetch Smartlead inbox ${inboxId}: ${error}`,
      );
      throw error;
    }
  }

  private async persistEmailAccount(
    entity: EmailAccountEntity,
  ): Promise<void> {
    await this.datastoreService.store(
      new StoreDataDto({
        data: entity,
        context: { documentType: documentType.EMAIL_ACCOUNT },
      }),
    );
  }

  async getEmailAccountByInboxId(
    smartleadInboxId: string,
  ): Promise<EmailAccountEntity | null> {
    const result = await this.datastoreService.getById({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    if (!result?.data) {
      return null;
    }
    return new EmailAccountEntity(result.data);
  }

  async getEmailAccountByEmail(
    email: string,
  ): Promise<EmailAccountEntity | null> {
    const result = await this.datastoreService.getByField({
      fieldKey: 'data.email',
      fieldValue: email,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    if (!result?.data?.length) {
      return null;
    }
    return new EmailAccountEntity(result.data[0]);
  }

  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccountEntity[]> {
    const result = await this.datastoreService.getByField({
      fieldKey: 'data.smartleadClientId',
      fieldValue: smartleadClientId,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return (result?.data || []).map((d) => new EmailAccountEntity(d));
  }

  async getEmailAccounts(
    filter: EmailAccountFilterDto,
  ): Promise<{ items: EmailAccountEntity[]; total: number; page: number; pageSize: number }> {
    const { page = 1, pageSize = 20, ...filters } = filter;
    const queryFilters: Record<string, any> = {};

    if (filters.smartleadClientId) {
      queryFilters['data.smartleadClientId'] = filters.smartleadClientId;
    }
    if (filters.email) {
      queryFilters['data.email'] = filters.email;
    }
    if (filters.smartleadInboxId) {
      queryFilters['data.smartleadInboxId'] = filters.smartleadInboxId;
    }
    if (filters.deliverabilityBand) {
      queryFilters['data.deliverabilityBand'] = filters.deliverabilityBand;
    }

    let result;
    if (Object.keys(queryFilters).length === 0) {
      result = await this.datastoreService.getByPattern({
        pattern: '',
        documentType: documentType.EMAIL_ACCOUNT,
      });
    } else {
      const primaryKey = Object.keys(queryFilters)[0];
      result = await this.datastoreService.getByField({
        fieldKey: primaryKey,
        fieldValue: queryFilters[primaryKey],
        documentType: documentType.EMAIL_ACCOUNT,
        pagination: { page, pageSize },
      });
    }

    let items = (result?.data || []).map((d) => new EmailAccountEntity(d));

    if (filters.tags?.length) {
      items = items.filter((account) =>
        filters.tags!.some((tag) => account.tags.includes(tag)),
      );
    }

    const total = items.length;
    const start = (page - 1) * pageSize;
    items = items.slice(start, start + pageSize);

    return { items, total, page, pageSize };
  }

  async deleteEmailAccount(smartleadInboxId: string): Promise<void> {
    this.logger.log(`Deleting email account: ${smartleadInboxId}`);
    const existing = await this.getEmailAccountByInboxId(smartleadInboxId);
    if (!existing) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }
    await this.datastoreService.remove({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });
  }

  async associateEmailAccountsWithCampaign(
    dto: AssociateCampaignDto,
  ): Promise<{ associated: string[]; skipped: string[] }> {
    const { emailAccountIds, campaignId } = dto;

    const uniqueIds = [...new Set(emailAccountIds)];
    if (uniqueIds.length !== emailAccountIds.length) {
      this.logger.warn(
        `Duplicate inbox IDs in request, treating as single: ${emailAccountIds.join(', ')}`,
      );
    }

    const accounts = await Promise.all(
      uniqueIds.map((id) => this.getEmailAccountByInboxId(id)),
    );

    const missing = uniqueIds.filter((_, i) => !accounts[i]);
    if (missing.length > 0) {
      throw new BadRequestException(
        `Email accounts not found: ${missing.join(', ')}`,
      );
    }

    const associated: string[] = [];
    const skipped: string[] = [];

    for (let i = 0; i < uniqueIds.length; i++) {
      const account = accounts[i]!;
      if (account.hasCampaign(campaignId)) {
        skipped.push(uniqueIds[i]);
      } else {
        account.addCampaignId(campaignId);
        await this.persistEmailAccount(account);
        associated.push(uniqueIds[i]);
      }
    }

    return { associated, skipped };
  }

  async dissociateEmailAccountFromCampaign(
    smartleadInboxId: string,
    campaignId: string,
  ): Promise<void> {
    const account = await this.getEmailAccountByInboxId(smartleadInboxId);
    if (!account) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }
    account.removeCampaignId(campaignId);
    await this.persistEmailAccount(account);
  }

  async getBestEmailAccountsForCampaign(
    dto: EmailAccountListDto,
  ): Promise<EmailAccountEntity[]> {
    const {
      smartleadClientId,
      campaignId,
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign = 10,
      emailsPerInboxPerDay = EMAILS_PER_INBOX_PER_DAY,
    } = dto;

    const requiredPool = Math.floor(
      totalNumberOfEmailsToSend / numberOfDaysInCampaign / emailsPerInboxPerDay,
    );

    this.logger.log(
      `Calculating best accounts for campaign ${campaignId}: need ${requiredPool} inboxes`,
    );

    const allAccounts = await this.getEmailAccountBySmartleadClientId(
      smartleadClientId,
    );

    if (allAccounts.length === 0) {
      this.logger.warn(`No email accounts found for client ${smartleadClientId}`);
      return [];
    }

    const domainCounts = new Map<string, number>();
    for (const account of allAccounts) {
      domainCounts.set(account.domain, (domainCounts.get(account.domain) || 0) + 1);
    }

    const scoredAccounts = allAccounts.map((account) => ({
      account,
      sameDomainCount: domainCounts.get(account.domain) || 0,
    }));

    scoredAccounts.sort((a, b) => {
      const scoreA = a.account.deliverabilityScore ?? -1;
      const scoreB = b.account.deliverabilityScore ?? -1;

      if (scoreB !== scoreA) {
        return scoreB - scoreA;
      }

      const campaignCountA = a.account.numberOfCampaignAssociated;
      const campaignCountB = b.account.numberOfCampaignAssociated;
      if (campaignCountA !== campaignCountB) {
        return campaignCountA - campaignCountB;
      }

      if (a.sameDomainCount !== b.sameDomainCount) {
        return a.sameDomainCount - b.sameDomainCount;
      }

      return (
        new Date(a.account.createdAt).getTime() -
        new Date(b.account.createdAt).getTime()
      );
    });

    return scoredAccounts.slice(0, requiredPool).map((s) => s.account);
  }

  async syncReputationFromSmartlead(
    smartleadClientId?: string,
  ): Promise<{ updated: number; failed: number }> {
    let accounts: EmailAccountEntity[];
    if (smartleadClientId) {
      accounts = await this.getEmailAccountBySmartleadClientId(smartleadClientId);
    } else {
      const result = await this.datastoreService.getByPattern({
        pattern: '',
        documentType: documentType.EMAIL_ACCOUNT,
      });
      accounts = (result?.data || []).map((d) => new EmailAccountEntity(d));
    }

    let updated = 0;
    let failed = 0;

    for (const account of accounts) {
      try {
        const inbox = await this.fetchSmartleadInbox(
          account.smartleadInboxId,
          account.smartleadClientId,
        );
        if (inbox && inbox.warmup_reputation !== undefined) {
          account.updateReputation(inbox.warmup_reputation);
          await this.persistEmailAccount(account);
          updated++;
        }
      } catch (error) {
        this.logger.error(
          `Failed to sync reputation for ${account.smartleadInboxId}: ${error}`,
        );
        failed++;
      }
    }

    return { updated, failed };
  }

  async importEmailAccountsFromSmartlead(
    smartleadClientId: string,
  ): Promise<{ imported: number; skipped: number; errors: string[] }> {
    try {
      const url = `${this.smartleadBaseUrl}/email-accounts?api_key=${this.smartleadApiKey}&client_id=${smartleadClientId}`;
      const res = await fetch(url);
      if (!res.ok) {
        throw new Error(`Smartlead API error: ${res.status}`);
      }
      const inboxes: SmartleadInboxResponseDto[] = await res.json();

      let imported = 0;
      let skipped = 0;
      const errors: string[] = [];

      for (const inbox of inboxes) {
        try {
          const existing = await this.getEmailAccountByInboxId(inbox.id);
          if (existing) {
            skipped++;
            continue;
          }

          const dto: EmailAccountDto = {
            smartleadInboxId: inbox.id,
            smartleadClientId,
            email: inbox.email,
            tags: inbox.tags || [],
            warmupReputation: inbox.warmup_reputation ?? null,
          };

          await this.saveEmailAccount(dto);
          imported++;
        } catch (error) {
          errors.push(`Failed to import ${inbox.id}: ${error}`);
        }
      }

      return { imported, skipped, errors };
    } catch (error) {
      this.logger.error(
        `Failed to import email accounts for client ${smartleadClientId}: ${error}`,
      );
      throw new InternalServerErrorException(
        `Failed to import email accounts: ${error}`,
      );
    }
  }
}

