import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
  UsePipes,
  ValidationPipe,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiQuery } from '@nestjs/swagger';
import { EmailinfraService } from './emailinfra.service';
import {
  EmailAccountDto,
  EmailAccountListDto,
  AssociateCampaignDto,
  EmailAccountFilterDto,
} from './dto/email-account.dto';

@ApiTags('emailinfra')
@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @Post('accounts')
  @UsePipes(new ValidationPipe({ transform: true, whitelist: true }))
  @ApiOperation({ summary: 'Create or update an email account' })
  @ApiResponse({ status: 201, description: 'Email account created/updated' })
  @ApiResponse({ status: 404, description: 'Smartlead inbox not found' })
  async saveEmailAccount(@Body() dto: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(dto);
  }

  @Get('accounts/:smartleadInboxId')
  @ApiOperation({ summary: 'Get email account by Smartlead inbox ID' })
  @ApiResponse({ status: 200, description: 'Email account found' })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  async getEmailAccountByInboxId(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ) {
    const account = await this.emailinfraService.getEmailAccountByInboxId(
      smartleadInboxId,
    );
    if (!account) {
      return { message: 'Email account not found' };
    }
    return account;
  }

  @Get('accounts/email/:email')
  @ApiOperation({ summary: 'Get email account by email address' })
  @ApiResponse({ status: 200, description: 'Email account found' })
  @ApiResponse({ status: 404, description: 'Email account not found' })
  async getEmailAccountByEmail(@Param('email') email: string) {
    const account = await this.emailinfraService.getEmailAccountByEmail(email);
    if (!account) {
      return { message: 'Email account not found' };
    }
    return account;
  }

  @Get('accounts/client/:smartleadClientId')
  @ApiOperation({ summary: 'Get all email accounts for a Smartlead client' })
  @ApiResponse({ status: 200, description: 'List of email accounts' })
  async getEmailAccountsByClient(
    @Param('smartleadClientId') smartleadClientId: string,
  ) {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(
